
import Script from 'next/script';

const bodyContent = "<!--\n  v4 — \"award\" pass. Same verified content and structure as the approved design; new:\n  layered hero (spotlight → giant AP monogram → portrait → content),\n  word/line reveals, curtain image reveals, scroll parallax, scroll-inked statement & quote,\n  scroll-drawn journey rail, scroll-driven type band, gold-sweep buttons, magnetic CTAs,\n  3D book tilt, hide-on-scroll header, animated drawer, footer wordmark.\n  All motion respects prefers-reduced-motion; pointer effects are desktop-only.\n  Facts carry data-src keys → SOURCES at the bottom.\n-->\n<a class=\"skip\" href=\"#main\">Skip to content</a>\n<div class=\"progress\" aria-hidden=\"true\"></div>\n\n<header class=\"hdr\" id=\"hdr\">\n  <div class=\"wrap\">\n    <a class=\"brand\" href=\"#top\"><i aria-hidden=\"true\"></i>Ananth Padmanabhan</a>\n    <nav class=\"nav\" aria-label=\"Primary\">\n      <ul>\n        <li><a href=\"#about\">About</a></li>\n        <li><a href=\"#ideas\">Ideas</a></li>\n        <li><a href=\"#journey\">Journey</a></li>\n        <li><a href=\"#institutions\">Institution Building</a></li>\n        <li><a href=\"#publications\">Publications</a></li>\n        <li><a href=\"#journal\">Journal &amp; Media</a></li>\n        <li class=\"ink\" aria-hidden=\"true\"></li>\n      </ul>\n      <a class=\"btn btn-dark magnetic\" href=\"#contact\">Contact</a>\n      <button class=\"menu-btn\" aria-expanded=\"false\" aria-controls=\"drawer\" aria-label=\"Open menu\"><i></i><i></i></button>\n    </nav>\n  </div>\n</header>\n<div class=\"drawer\" id=\"drawer\" aria-hidden=\"true\">\n  <ul>\n    <li><a href=\"#about\" style=\"--i:0\">About</a></li>\n    <li><a href=\"#ideas\" style=\"--i:1\">Ideas</a></li>\n    <li><a href=\"#journey\" style=\"--i:2\">Journey</a></li>\n    <li><a href=\"#institutions\" style=\"--i:3\">Institution Building</a></li>\n    <li><a href=\"#publications\" style=\"--i:4\">Publications</a></li>\n    <li><a href=\"#journal\" style=\"--i:5\">Journal &amp; Media</a></li>\n  </ul>\n  <div class=\"foot\">\n    <a class=\"btn btn-dark\" href=\"#contact\">Contact <span class=\"ar\" aria-hidden=\"true\">→</span></a>\n    <p>Founding Vice-Chancellor, Sreenidhi University</p>\n  </div>\n</div>\n\n<main id=\"main\">\n\n<!-- ================= 01 HERO ================= -->\n<section class=\"hero\" data-px-host id=\"top\" aria-labelledby=\"h-title\">\n  <div class=\"grain\" aria-hidden=\"true\"></div>\n  <div class=\"wrap hero-stage\">\n    <div class=\"hero-main\">\n      <div class=\"hero-copy\">\n        <p class=\"kicker fade\" style=\"--t:.3s\">\n          <svg width=\"14\" height=\"14\" viewBox=\"0 0 14 14\" fill=\"none\" aria-hidden=\"true\"><path d=\"M1 4.5 7 1l6 3.5M2 5.5v5M5 5.5v5M9 5.5v5M12 5.5v5M1 12.5h12\" stroke=\"#D6AE6A\" stroke-width=\"1.2\"/></svg>\n          Legal Scholar • Institution Builder\n        </p>\n        <h1 class=\"h1\" id=\"h-title\">\n          <span class=\"l\"><span>Law.</span></span>\n          <span class=\"l\"><span>Technology.</span></span>\n          <span class=\"l\"><span class=\"gold\">Institutions.</span></span>\n        </h1>\n        <div class=\"hero-sub fade\" style=\"--t:1s\">\n          <p><strong>Ananth Padmanabhan</strong> works across law, technology, public policy and higher education.</p>\n        </div>\n      </div>\n\n      <div class=\"hero-visual\">\n        <div class=\"mono\" aria-hidden=\"true\" data-speed=\"-0.12\" data-mouse=\"18\"><span>A</span><span>P</span></div>\n        <div class=\"hero-portrait\"><div class=\"pl\" data-speed=\"0.06\" data-mouse=\"-8\"><img src=\"data:image/png;base64,\" alt=\"Portrait of Ananth Padmanabhan, smiling, in glasses, a charcoal bandhgala waistcoat and a lilac shirt\" width=\"1000\" height=\"1005\" fetchpriority=\"high\"></div></div>\n      </div>\n\n      <aside class=\"focus\" aria-label=\"Areas of focus\">\n        <div class=\"t\">Areas of Focus</div>\n        <ul>\n          <li><span class=\"ic\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 16 16\" fill=\"none\" aria-hidden=\"true\"><rect x=\"1.5\" y=\"2.5\" width=\"13\" height=\"9\" rx=\"1\" stroke=\"#fff\" stroke-width=\"1.1\"/><path d=\"M5.5 14h5M8 11.5V14\" stroke=\"#fff\" stroke-width=\"1.1\"/></svg></span>Technology &amp; Law</li>\n          <li><span class=\"ic\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 16 16\" fill=\"none\" aria-hidden=\"true\"><circle cx=\"8\" cy=\"8\" r=\"6.3\" stroke=\"#fff\" stroke-width=\"1.1\"/><path d=\"M10.2 6.3A2.6 2.6 0 1 0 10.2 9.7\" stroke=\"#fff\" stroke-width=\"1.1\"/></svg></span>Intellectual Property</li>\n          <li><span class=\"ic\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 16 16\" fill=\"none\" aria-hidden=\"true\"><path d=\"M3.5 1.5h6l3 3v10h-9z\" stroke=\"#fff\" stroke-width=\"1.1\"/><path d=\"M6 8.5h4M6 11h4\" stroke=\"#fff\" stroke-width=\"1.1\"/></svg></span>Public Policy &amp; Regulation</li>\n          <li><span class=\"ic\"><svg width=\"16\" height=\"16\" viewBox=\"0 0 16 16\" fill=\"none\" aria-hidden=\"true\"><path d=\"M1 6 8 2.5 15 6 8 9.5z\" stroke=\"#fff\" stroke-width=\"1.1\"/><path d=\"M4 7.6v3.2c1.1 1 2.5 1.6 4 1.6s2.9-.6 4-1.6V7.6\" stroke=\"#fff\" stroke-width=\"1.1\"/></svg></span>Higher Education</li>\n        </ul>\n        <!-- The single \"Explore His Work\" CTA on the page -->\n        <a class=\"btn magnetic\" href=\"#ideas\">Explore His Work <span class=\"ar\" aria-hidden=\"true\">→</span></a>\n      </aside>\n    </div>\n  </div>\n\n</section>\n\n<!-- ================= 02 ABOUT ================= -->\n<section class=\"sec\" id=\"about\" aria-labelledby=\"ab-h\">\n  <div class=\"wrap\">\n    <span class=\"eyebrow rv\" id=\"ab-h\">About</span>\n    <p class=\"stmt\" id=\"stmt\" data-hl=\"one question:\">From the courtroom to the classroom, the policy room and the vice-chancellor’s office, Ananth Padmanabhan has returned to one question: how should institutions respond when technology changes faster than they do?</p>\n    <div class=\"about-grid\">\n      <div class=\"rv\">\n        <p class=\"lead\">These are the questions that have shaped much of his work — in litigation, doctoral research, technology policy and the building of new schools of law.</p>\n        <a class=\"tlink\" href=\"#journey\">Follow the Journey <span class=\"ar\" aria-hidden=\"true\">→</span></a>\n      </div>\n      <ul class=\"qs\" id=\"qs\">\n        <li class=\"rv\" style=\"--d:1\"><button class=\"q-btn\" id=\"qb-1\" aria-expanded=\"false\" aria-controls=\"qa-1\"><span>What happens when technology moves faster than law?</span><span class=\"pm\" aria-hidden=\"true\"></span></button>\n          <div class=\"q-a\" id=\"qa-1\" role=\"region\" aria-labelledby=\"qb-1\"><div><p>It is the thread through his research and writing — from copyright and digital media in his doctoral work to civilian drones, deepfakes and competition law for the digital age: how rules can keep pace with technologies whose consequences arrive first.</p><a class=\"tlink\" href=\"#journal\">Read the latest thinking <span class=\"ar\" aria-hidden=\"true\">→</span></a></div></div></li>\n        <li class=\"rv\" style=\"--d:2\"><button class=\"q-btn\" id=\"qb-2\" aria-expanded=\"false\" aria-controls=\"qa-2\"><span>What should universities teach for careers that do not yet exist?</span><span class=\"pm\" aria-hidden=\"true\"></span></button>\n          <div class=\"q-a\" id=\"qa-2\" role=\"region\" aria-labelledby=\"qb-2\"><div><p>The question behind the programmes he has built — the Daksha Fellowship in technology law and policy, a one-year LL.M. in regulatory studies, and now a multidisciplinary university that includes the Sreenidhi School of Business.</p><a class=\"tlink\" href=\"#institutions\">See the institutions <span class=\"ar\" aria-hidden=\"true\">→</span></a></div></div></li>\n        <li class=\"rv\" style=\"--d:3\"><button class=\"q-btn\" id=\"qb-3\" aria-expanded=\"false\" aria-controls=\"qa-3\"><span>How do institutions designed for yesterday respond to tomorrow?</span><span class=\"pm\" aria-hidden=\"true\"></span></button>\n          <div class=\"q-a\" id=\"qa-3\" role=\"region\" aria-labelledby=\"qb-3\"><div><p>Answered in practice: as founding dean of Sai University’s School of Law, as dean at Vinayaka Mission’s Law School, and now as founding Vice-Chancellor of Sreenidhi University.</p><a class=\"tlink\" href=\"#journey\">Follow the Journey <span class=\"ar\" aria-hidden=\"true\">→</span></a></div></div></li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- ================= 03 IDEAS ================= -->\n<section class=\"sec\" id=\"ideas\" aria-labelledby=\"id-h\" style=\"padding-top:0\">\n  <div class=\"wrap\">\n    <div class=\"shead\">\n      <div><span class=\"eyebrow rv\">Ideas</span><h2 class=\"h2 split\" id=\"id-h\">Ideas I Keep Returning To</h2></div>\n      <p class=\"lead rv\" style=\"--d:2\">Four territories that run through the scholarship, the policy work and the institutions — each one a question rather than a service line.</p>\n    </div>\n    <div class=\"tiles\">\n      <a class=\"tile\" href=\"#journal\"><div class=\"reveal\" style=\"--d:0\"><div class=\"zoom\"><img src=\"data:image/jpeg;base64,\" alt=\"\" width=\"760\" height=\"950\"></div></div><div class=\"tb\"><span class=\"n\">01<span class=\"go\" aria-hidden=\"true\">→</span></span><h3>Law &amp; Public Policy</h3><p><span>How do laws become institutions, incentives and, ultimately, societal outcomes?</span></p></div></a>\n      <a class=\"tile\" href=\"#journal\"><div class=\"reveal\" style=\"--d:1\"><div class=\"zoom\"><img src=\"data:image/jpeg;base64,\" alt=\"\" width=\"760\" height=\"950\"></div></div><div class=\"tb\"><span class=\"n\">02<span class=\"go\" aria-hidden=\"true\">→</span></span><h3>Technology &amp; AI Regulation</h3><p><span>How should societies govern technologies whose consequences evolve faster than regulation?</span></p></div></a>\n      <a class=\"tile\" href=\"#publications\"><div class=\"reveal\" style=\"--d:2\"><div class=\"zoom\"><img src=\"data:image/jpeg;base64,\" alt=\"\" width=\"760\" height=\"950\"></div></div><div class=\"tb\"><span class=\"n\">03<span class=\"go\" aria-hidden=\"true\">→</span></span><h3>Intellectual Property &amp; Innovation</h3><p><span>How can IP frameworks encourage innovation while balancing competing public interests?</span></p></div></a>\n      <a class=\"tile\" href=\"#institutions\"><div class=\"reveal\" style=\"--d:3\"><div class=\"zoom\"><img src=\"data:image/jpeg;base64,\" alt=\"\" width=\"760\" height=\"950\"></div></div><div class=\"tb\"><span class=\"n\">04<span class=\"go\" aria-hidden=\"true\">→</span></span><h3>Higher Education &amp; Institutions</h3><p><span>What should universities teach when knowledge, technology and work are all changing at once?</span></p></div></a>\n    </div>\n  </div>\n</section>\n\n<!-- ================= 04 JOURNEY ================= -->\n<section class=\"sec\" id=\"journey\" aria-labelledby=\"jr-h\" style=\"padding-top:0\">\n  <div class=\"wrap jr\">\n    <div class=\"jr-intro\">\n      <span class=\"eyebrow rv\">Journey</span>\n      <h2 class=\"h2 split\" id=\"jr-h\">From the Courtroom to the University</h2>\n      <p class=\"lead rv\" style=\"--d:2\">Lawyer, scholar, policy researcher, institution builder, university leader. Open any chapter for the detail.</p>\n      <p class=\"lead rv\" style=\"--d:3\" data-src=\"scc penn\">B.A. LL.B. (Hons.), NLSIU · LL.M. and S.J.D., Penn Carey Law · MSx, Stanford GSB</p>\n    </div>\n    <ol class=\"rows\" id=\"rows\">\n      <li class=\"rail\" aria-hidden=\"true\"><b></b></li>\n      <li class=\"row rv\" data-src=\"li\"><button aria-expanded=\"false\"><span class=\"yr\">2008</span><span class=\"ro\">Advocate<span class=\"inst-m\">The High Court of Madras</span></span><span class=\"inst\">The High Court of Madras</span><span class=\"pm\" aria-hidden=\"true\"></span></button>\n        <div class=\"det\"><div><p>Disputes practice across judicial fora, with specialised work in intellectual property and copyright — including counsel for sound recording labels and copyright societies, and advisory work on the Copyright (Amendment) Act, 2012.</p></div></div></li>\n      <li class=\"row rv\" data-src=\"penn li\"><button aria-expanded=\"false\"><span class=\"yr\">2013</span><span class=\"ro\">LL.M. &amp; S.J.D.<span class=\"inst-m\">Penn Carey Law</span></span><span class=\"inst\">Penn Carey Law</span><span class=\"pm\" aria-hidden=\"true\"></span></button>\n        <div class=\"det\"><div><p>A doctoral thesis on copyright and digital media — <em>Copyright’s Technology Play</em> — alongside work with Penn’s Center for Technology, Innovation and Competition.</p></div></div></li>\n      <li class=\"row rv\" data-src=\"li carn\"><button aria-expanded=\"false\"><span class=\"yr\">2016</span><span class=\"ro\">Fellow<span class=\"inst-m\">Carnegie India, New Delhi</span></span><span class=\"inst\">Carnegie India, New Delhi</span><span class=\"pm\" aria-hidden=\"true\"></span></button>\n        <div class=\"det\"><div><p>Technology, regulation and public policy — drones, biotech, the digital economy and data protection. Built the technology and policy vertical and organised two editions of the Global Technology Summit.</p></div></div></li>\n      <li class=\"row rv\" data-src=\"cpr li na\"><button aria-expanded=\"false\"><span class=\"yr\">2018</span><span class=\"ro\">Research Fellowships<span class=\"inst-m\">Centre for Policy Research · New America</span></span><span class=\"inst\">Centre for Policy Research · New America</span><span class=\"pm\" aria-hidden=\"true\"></span></button>\n        <div class=\"det\"><div><p>A programme on public law and new technologies at CPR, and research on the privacy implications of civilian drones as a U.S.–India Public Interest Technology Fellow in Washington, D.C.</p></div></div></li>\n      <li class=\"row rv\" data-src=\"li scc\"><button aria-expanded=\"false\"><span class=\"yr\">2019</span><span class=\"ro\">Founding Dean, School of Law<span class=\"inst-m\">Sai University, Chennai</span></span><span class=\"inst\">Sai University, Chennai</span><span class=\"pm\" aria-hidden=\"true\"></span></button>\n        <div class=\"det\"><div><p>Also Dean of Academic Affairs. Architected the Daksha Fellowship in technology law and policy, a one-year LL.M. in regulatory studies, and a Water Law Initiative.</p></div></div></li>\n      <li class=\"row rv\" data-src=\"li penn\"><button aria-expanded=\"false\"><span class=\"yr\">2022</span><span class=\"ro\">MSx Sloan Fellow<span class=\"inst-m\">Stanford GSB</span></span><span class=\"inst\">Stanford GSB</span><span class=\"pm\" aria-hidden=\"true\"></span></button>\n        <div class=\"det\"><div><p>A deliberate mid-career return to learning — widening the lens from law to management and leadership.</p></div></div></li>\n      <li class=\"row rv\" data-src=\"li scc\"><button aria-expanded=\"false\"><span class=\"yr\">2023</span><span class=\"ro\">Dean, School of Law<span class=\"inst-m\">Vinayaka Mission’s Law School</span></span><span class=\"inst\">Vinayaka Mission’s Law School</span><span class=\"pm\" aria-hidden=\"true\"></span></button>\n        <div class=\"det\"><div><p>A new vision for legal education in India, focused on excellence through inclusivity.</p></div></div></li>\n      <li class=\"row rv\" data-src=\"li tt1 tt2\"><button aria-expanded=\"false\"><span class=\"yr\">2026</span><span class=\"ro\">Founding Vice-Chancellor<span class=\"now-tag\">Now</span><span class=\"inst-m\">Sreenidhi University, Hyderabad</span></span><span class=\"inst\">Sreenidhi University, Hyderabad</span><span class=\"pm\" aria-hidden=\"true\"></span></button>\n        <div class=\"det\"><div><p>Leading a young, multidisciplinary university — including the launch of the Sreenidhi School of Business in March 2026.</p></div></div></li>\n    </ol>\n  </div>\n</section>\n\n<!-- ================= BIG TYPE BAND (transition) ================= -->\n<div class=\"band\" aria-hidden=\"true\">\n  <div class=\"band-track\" id=\"bandTrack\">\n    <span class=\"band-line\"><span class=\"w\">Law</span><span class=\"dot\">●</span><span class=\"w\">Technology</span><span class=\"dot\">●</span><span class=\"w\">Public Policy</span></span>\n    <span class=\"band-line\"><span class=\"w\">Higher Education</span><span class=\"dot\">●</span><span class=\"w\">Institutions</span></span>\n  </div>\n</div>\n\n<!-- ================= 05 INSTITUTION BUILDING ================= -->\n<section class=\"inst-sec\" id=\"institutions\" aria-labelledby=\"in-h\">\n  <div class=\"inst-txt\">\n    <div class=\"inst-head\">\n    <span class=\"eyebrow rv\">Institution Building</span>\n    <h2 class=\"h2 split\" id=\"in-h\">Building Institutions, Not Just Studying Them</h2>\n    <div class=\"slides rv\" style=\"--d:2\" aria-live=\"polite\">\n      <article class=\"slide\" id=\"sl-0\" role=\"tabpanel\" aria-labelledby=\"tb-0\" data-src=\"li cd scc\">\n        <span class=\"eyebrow\">2019 – 2022 · Founding Dean</span>\n        <h3>Sai University School of Law &amp; the Daksha Fellowship</h3>\n        <p>A new law school within a new university, built around collaborative, experiential learning for lawyers working across technology, law and business.</p>\n        <ul><li>Daksha Fellowship in technology law and policy</li><li>One-year LL.M. in regulatory studies</li><li>Water Law Initiative</li></ul>\n      </article>\n      <article class=\"slide\" id=\"sl-1\" role=\"tabpanel\" aria-labelledby=\"tb-1\" data-src=\"li scc\">\n        <span class=\"eyebrow\">2023 – 2025 · Dean, School of Law</span>\n        <h3>Vinayaka Mission’s Law School, Chennai</h3>\n        <p>A new vision for legal education in India — excellence through inclusivity — shaped by a concern he named on joining: “the deficient feeder of quality in the lower levels of the system, particularly district courts.”</p>\n      </article>\n      <article class=\"slide on\" id=\"sl-2\" role=\"tabpanel\" aria-labelledby=\"tb-2\" data-src=\"li tt1 tt2\">\n        <span class=\"eyebrow\">Since 2026 · Founding Vice-Chancellor</span>\n        <h3>Sreenidhi University, Hyderabad</h3>\n        <p>A multidisciplinary university, now including the Sreenidhi School of Business — built on universities as places that nurture intellectual curiosity, critical inquiry and interdisciplinary collaboration.</p>\n      </article>\n    </div>\n    </div>\n    <div class=\"inst-nav rv\" style=\"--d:3\">\n      <div class=\"tabs\" role=\"tablist\" aria-label=\"Institutions\">\n        <button role=\"tab\" id=\"tb-0\" aria-selected=\"false\" aria-controls=\"sl-0\" tabindex=\"-1\">Sai University</button>\n        <button role=\"tab\" id=\"tb-1\" aria-selected=\"false\" aria-controls=\"sl-1\" tabindex=\"-1\">Vinayaka Missions</button>\n        <button role=\"tab\" id=\"tb-2\" aria-selected=\"true\" aria-controls=\"sl-2\">Sreenidhi University</button>\n      </div>\n      <div class=\"tab-timer\" aria-hidden=\"true\"><b id=\"tabTimer\"></b></div>\n    </div>\n  </div>\n  <div class=\"inst-img\"><div class=\"reveal\" style=\"position:absolute;inset:0\"><div class=\"px\" data-speed=\"0.12\" id=\"instFrames\"><img class=\"inst-frame on\" data-i=\"2\" src=\"data:image/jpeg;base64,\" alt=\"\" width=\"1920\" height=\"823\" fetchpriority=\"high\" decoding=\"async\"></div></div>\n    <div class=\"inst-cap\" id=\"instCap\" aria-hidden=\"true\"><span class=\"k\">Since 2026 · Founding Vice-Chancellor</span><span class=\"t\">Sreenidhi University, Hyderabad</span></div>\n  </div>\n</section>\n\n<!-- ================= 06 PUBLICATIONS ================= -->\n<section class=\"sec\" id=\"publications\" aria-labelledby=\"pb-h\">\n  <div class=\"wrap\">\n    <div class=\"shead\">\n      <div><span class=\"eyebrow rv\">Publications</span><h2 class=\"h2 split\" id=\"pb-h\">Books &amp; Scholarship</h2></div>\n      <p class=\"lead rv\" style=\"--d:2\">A treatise on intellectual property remedies, an Oxford volume on Indian innovation, and research on constitutional rights, copyright and technology regulation.</p>\n    </div>\n    <div class=\"pub\">\n      <article class=\"book rv\" data-src=\"li spicy carn\">\n        <a class=\"cover tilt\" href=\"https://books.google.com/books/about/Intellectual_Property_Rights.html?id=yHeVoAEACAAJ\" target=\"_blank\" rel=\"noopener\"><img src=\"data:image/jpeg;base64,\" alt=\"Cover of Intellectual Property Rights: Infringement and Remedies by Ananth Padmanabhan, LexisNexis Butterworths Wadhwa\" width=\"480\" height=\"732\"></a>\n        <span class=\"eyebrow\">Book · 2012</span>\n        <h3>Intellectual Property Rights: Infringement and Remedies</h3>\n        <p class=\"meta\">LexisNexis Butterworths Wadhwa</p>\n      </article>\n      <article class=\"book rv\" style=\"--d:1\" data-src=\"oup1\">\n        <a class=\"cover tilt\" href=\"https://academic.oup.com/book/2618\" target=\"_blank\" rel=\"noopener\"><img src=\"data:image/jpeg;base64,\" alt=\"Cover of India as a Pioneer of Innovation, edited by Harbir Singh, Ananth Padmanabhan and Ezekiel J. Emanuel, Oxford University Press\" width=\"360\" height=\"539\"></a>\n        <span class=\"eyebrow\">Edited volume · 2017</span>\n        <h3>India as a Pioneer of Innovation</h3>\n        <p class=\"meta\">Oxford University Press · co-editor</p>\n      </article>\n      <div class=\"slist rv\" style=\"--d:2\">\n        <span class=\"eyebrow\">Selected scholarship</span>\n        <ul>\n          <li><a href=\"https://carnegieendowment.org/research/2017/03/civilian-drones-and-indias-regulatory-response?lang=en&amp;center=india\" target=\"_blank\" rel=\"noopener\" data-src=\"ci\"><span><span class=\"t\">Civilian Drones and India’s Regulatory Response</span><span class=\"s\">Carnegie Endowment · Paper · 2017</span></span><span class=\"ar\" aria-hidden=\"true\">↗</span></a></li>\n          <li><a href=\"https://academic.oup.com/edited-volume/42606/chapter-abstract/357548300\" target=\"_blank\" rel=\"noopener\" data-src=\"oup2\"><span><span class=\"t\">Rights: breadth, scope, and applicability</span><span class=\"s\">Oxford Handbook of the Indian Constitution · 2016</span></span><span class=\"ar\" aria-hidden=\"true\">↗</span></a></li>\n          <li><a href=\"https://www.law.upenn.edu/live/profiles/498-ananth-padmanabhan\" target=\"_blank\" rel=\"noopener\" data-src=\"penn\"><span><span class=\"t\">Copyright’s Technology Play</span><span class=\"s\">S.J.D. dissertation · Penn Carey Law · 2019</span></span><span class=\"ar\" aria-hidden=\"true\">↗</span></a></li>\n          <li><a href=\"https://carnegieendowment.org/europe/research/2017/05/the-right-way-to-nurture-indias-digital-economy\" target=\"_blank\" rel=\"noopener\" data-src=\"ci\"><span><span class=\"t\">The Right Way to Nurture India’s Digital Economy</span><span class=\"s\">Carnegie Endowment · Research · 2017</span></span><span class=\"ar\" aria-hidden=\"true\">↗</span></a></li>\n        </ul>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- ================= 07 LATEST THINKING ================= -->\n<section class=\"sec\" id=\"journal\" aria-labelledby=\"jn-h\" style=\"padding-top:0\">\n  <div class=\"wrap\">\n    <div class=\"shead\">\n      <div><span class=\"eyebrow rv\">Journal &amp; Media</span><h2 class=\"h2 split\" id=\"jn-h\">Latest Thinking</h2></div>\n      <p class=\"lead rv\" style=\"--d:2\">Research and commentary on technology regulation, privacy, platforms and copyright — published by policy institutes and national newspapers.</p>\n    </div>\n    <a class=\"feature rv\" href=\"https://www.newamerica.org/insights/anthology-working-papers-new-americas-us-india-fellows/civilian-drones-privacy-challenges-and-potential-resolution-ananth-padmanabhan/\" target=\"_blank\" rel=\"noopener\" data-src=\"na\">\n      <div class=\"img\"><div class=\"reveal\"><div class=\"px\" data-speed=\"0.1\"><div class=\"zoom\"><img src=\"data:image/jpeg;base64,\" alt=\"\" width=\"1100\" height=\"825\" style=\"width:100%;height:100%;object-fit:cover\"></div></div></div></div>\n      <div class=\"txt\">\n        <span class=\"eyebrow\">Working paper · New America · 2019</span>\n        <h3>Civilian Drones: Privacy Challenges and Potential Resolution</h3>\n        <p>Separates the familiar surveillance problem from the newer one — the aggregation and analysis of drone-collected data — and proposes legal and technological responses, including privacy impact assessments within India’s Digital Sky platform.</p>\n        <span class=\"btn\">Read Article <span class=\"ar\" aria-hidden=\"true\">→</span></span>\n      </div>\n    </a>\n    <div class=\"cards\">\n      <a class=\"card rv\" href=\"https://www.hindustantimes.com/analysis/address-the-deepfake-problem-analysis/story-bKr6xurL0XFlezAkxM5NwN.html\" target=\"_blank\" rel=\"noopener\" data-src=\"cpr\"><span class=\"eyebrow\">Analysis · Hindustan Times</span><h4>Address the deepfake problem</h4><span class=\"foot\"><span>26 Feb 2020</span><span class=\"ar\" aria-hidden=\"true\">↗</span></span></a>\n      <a class=\"card rv\" style=\"--d:1\" href=\"https://www.hindustantimes.com/analysis/reforming-competition-law-for-the-digital-age/story-vwawHpH3NrDZcCCFTE70AI.html\" target=\"_blank\" rel=\"noopener\" data-src=\"cpr\"><span class=\"eyebrow\">Analysis · Hindustan Times</span><h4>Reforming competition law for the digital age</h4><span class=\"foot\"><span>17 Feb 2020</span><span class=\"ar\" aria-hidden=\"true\">↗</span></span></a>\n      <a class=\"card rv\" style=\"--d:2\" href=\"https://carnegieendowment.org/events/2018/04/technology-and-global-governance-a-conversation-with-ananth-padmanabhan?lang=en\" target=\"_blank\" rel=\"noopener\" data-src=\"ci\"><span class=\"eyebrow\">Conversation · Carnegie · Beijing</span><h4>Technology and Global Governance: A Conversation with Ananth Padmanabhan</h4><span class=\"foot\"><span>25 Apr 2018</span><span class=\"ar\" aria-hidden=\"true\">↗</span></span></a>\n    </div>\n  </div>\n</section>\n\n<!-- ================= 08 CONTACT ================= -->\n<section class=\"contact\" id=\"contact\" aria-labelledby=\"ct-h\">\n  <div class=\"img\"><div class=\"reveal\"><div class=\"px\" data-speed=\"0.1\"><img src=\"data:image/jpeg;base64,\" alt=\"Ananth Padmanabhan standing in his office, leaning against a desk, smiling\" width=\"900\" height=\"1350\"></div></div></div>\n  <div class=\"txt\">\n    <div class=\"top\"><span class=\"eyebrow rv\">Contact</span></div>\n    <h2 class=\"h2 split\" id=\"ct-h\">Continue the <em>Conversation</em></h2>\n    <p class=\"lead rv\" style=\"--d:2\">For speaking invitations, academic collaboration, research, media and institutional partnerships.</p>\n    <ul class=\"chips rv\" style=\"--d:3\"><li>Speaking</li><li>Academic collaboration</li><li>Research</li><li>Media</li><li>Institutional partnerships</li></ul>\n    <div class=\"actions rv\" style=\"--d:4\">\n      <!-- TODO: point to the client-approved enquiry form/address when available. LinkedIn is the verified channel today. -->\n      <a class=\"btn btn-light magnetic\" href=\"https://www.linkedin.com/in/ananthpadmanabhan1\" target=\"_blank\" rel=\"noopener\">Start a Conversation <span class=\"ar\" aria-hidden=\"true\">→</span></a>\n      <a class=\"btn btn-line magnetic\" href=\"#publications\">Publications</a>\n    </div>\n  </div>\n</section>\n\n<!-- ================= 09 IN HIS WORDS ================= -->\n<section class=\"quote\" aria-label=\"In his words\">\n  <div class=\"qm\" aria-hidden=\"true\">“</div>\n  <div class=\"wrap g\">\n    <div class=\"lab\"><span class=\"eyebrow rv\">In his words</span></div>\n    <blockquote data-src=\"penn\">\n      <p id=\"quoteText\">“The journey made me ask deep questions, engage with interdisciplinary research, think big picture, and construct ambitious and novel policy frameworks.”</p>\n      <footer class=\"rv\">On his doctoral work — <a href=\"https://www.law.upenn.edu/live/profiles/498-ananth-padmanabhan\" target=\"_blank\" rel=\"noopener\">Penn Carey Law</a></footer>\n    </blockquote>\n  </div>\n</section>\n</main>\n\n<footer class=\"ftr\">\n  <div class=\"wrap\">\n    <div class=\"g\">\n      <div><span class=\"brand\">Ananth Padmanabhan</span><p>Legal scholar, institution builder and university leader — working across law, technology, public policy and higher education.</p></div>\n      <div><h5>Explore</h5><ul><li><a href=\"#about\">About</a></li><li><a href=\"#ideas\">Ideas</a></li><li><a href=\"#journey\">Journey</a></li></ul></div>\n      <div><h5>Work</h5><ul><li><a href=\"#institutions\">Institution Building</a></li><li><a href=\"#publications\">Publications</a></li><li><a href=\"#journal\">Journal &amp; Media</a></li></ul></div>\n      <div><h5>Connect</h5><ul><li><a href=\"https://www.linkedin.com/in/ananthpadmanabhan1\" target=\"_blank\" rel=\"noopener\">LinkedIn</a></li><li><a href=\"#contact\">Contact</a></li></ul></div>\n    </div>\n    <div class=\"wordmark\" aria-hidden=\"true\"><span>Ananth</span> <span>Padmanabhan</span></div>\n    <div class=\"base\"><span>© <span id=\"yr\">2026</span> Ananth Padmanabhan · Law · Technology · Institutions</span><a class=\"to-top\" href=\"#top\">Back to top <i aria-hidden=\"true\">↑</i></a></div>\n  </div>\n</footer>\n\n";

